exercises.starter:
def tiered_cost(gb, tiers):
    """tiers: [(size of the tier in GB, or None for 'everything after'), USD per GB], in order.
    This version charges every GB at the price of the tier the total falls in."""
    start = 0
    for size, price in tiers:
        if size is None or gb <= start + size:
            return gb * price
        start += size

exercises.reference:
def tiered_cost(gb, tiers):
    cost, left = 0.0, gb
    for size, price in tiers:
        part = left if size is None else min(left, size)
        cost += part * price          # each tier's price applies only to the GB inside it
        left -= part
        if left <= 0:
            break
    return cost
